import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import type { StateCreator } from 'zustand';

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

export interface AppNotification {
  id: string;
  title: string;
  message: string;
  type: 'info' | 'success' | 'warning' | 'error';
  read: boolean;
  createdAt: string;
  link?: string;
}

/* ------------------------------------------------------------------ */
/*  State & Actions                                                    */
/* ------------------------------------------------------------------ */

interface NotificationState {
  /* -- state -- */
  notifications: AppNotification[];
  unreadCount: number;

  /* -- actions -- */
  addNotification: (notification: Omit<AppNotification, 'id' | 'createdAt' | 'read'>) => void;
  markRead: (id: string) => void;
  markAllRead: () => void;
  dismiss: (id: string) => void;
}

/* ------------------------------------------------------------------ */
/*  Helpers                                                            */
/* ------------------------------------------------------------------ */

function generateNotificationId(): string {
  return `ntf_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;
}

/* ------------------------------------------------------------------ */
/*  Store factory                                                      */
/* ------------------------------------------------------------------ */

const notificationStoreFactory: StateCreator<NotificationState> = (set) => ({
  /* -- initial state -- */
  notifications: [],
  unreadCount: 0,

  /* -- addNotification -- */
  addNotification: (notification): void => {
    const newNotification: AppNotification = {
      ...notification,
      read: false,
      id: generateNotificationId(),
      createdAt: new Date().toISOString(),
    };
    set((state) => ({
      notifications: [newNotification, ...state.notifications],
      unreadCount: state.unreadCount + 1,
    }));
  },

  /* -- markRead -- */
  markRead: (id): void => {
    set((state) => {
      const wasUnread = state.notifications.find((n) => n.id === id && !n.read);
      return {
        notifications: state.notifications.map((n) =>
          n.id === id ? { ...n, read: true } : n
        ),
        unreadCount: wasUnread ? state.unreadCount - 1 : state.unreadCount,
      };
    });
  },

  /* -- markAllRead -- */
  markAllRead: (): void => {
    set((state) => ({
      notifications: state.notifications.map((n) =>
        n.read ? n : { ...n, read: true }
      ),
      unreadCount: 0,
    }));
  },

  /* -- dismiss -- */
  dismiss: (id): void => {
    set((state) => {
      const wasUnread = state.notifications.find((n) => n.id === id && !n.read);
      return {
        notifications: state.notifications.filter((n) => n.id !== id),
        unreadCount: wasUnread ? state.unreadCount - 1 : state.unreadCount,
      };
    });
  },
});

/* ------------------------------------------------------------------ */
/*  Computed selectors                                                 */
/* ------------------------------------------------------------------ */

export function selectUnreadCount(state: NotificationState): number {
  return state.notifications.filter((n) => !n.read).length;
}

export function selectUnreadNotifications(state: NotificationState): AppNotification[] {
  return state.notifications.filter((n) => !n.read);
}

export function selectReadNotifications(state: NotificationState): AppNotification[] {
  return state.notifications.filter((n) => n.read);
}

export function selectNotificationsByType(
  state: NotificationState,
  type: AppNotification['type']
): AppNotification[] {
  return state.notifications.filter((n) => n.type === type);
}

/* ------------------------------------------------------------------ */
/*  Store export                                                       */
/* ------------------------------------------------------------------ */

export const useNotificationStore = create<NotificationState>()(
  persist(notificationStoreFactory, {
    name: 'azfit-notifications-storage',
    partialize: (state) => ({
      notifications: state.notifications,
    }),
  })
);
