/** Generate realistic BioPrint (skinfold) entries. */
function generateBioPrints(baseSeed: number, count: number): BioPrintEntry[] {
  const rng = seededRandom(baseSeed + 100);
  const sites: BioPrintEntry['site'][] = ['tricep', 'subscapular', 'suprailiac', 'thigh', 'abdominal'];
  const entries: BioPrintEntry[] = [];
  for (let i = 0; i < count; i++) {
    const date = addDays(getTodayISO(), -randInt(7, 90, rng));
    for (const site of sites) {
      entries.push({
        id: `bp-${i}-${site}`,
        date,
        site,
        value: randInt(6, 28, rng),
      });
    }
  }
  return entries;
}

/** Generate body measurement history. */
function generateMeasurements(baseSeed: number, count: number): BodyMeasurement[] {
  const rng = seededRandom(baseSeed + 200);
  const entries: BodyMeasurement[] = [];
  for (let i = 0; i < count; i++) {
    entries.push({
      id: `meas-${i}`,
      date: addDays(getTodayISO(), -randInt(7, 120, rng)),
      weight: randInt(55, 95, rng),
      bodyFat: randInt(12, 32, rng),
      chest: randInt(80, 110, rng),
      waist: randInt(60, 95, rng),
      hips: randInt(80, 105, rng),
      arms: randInt(25, 40, rng),
      thighs: randInt(45, 65, rng),
      shoulders: randInt(95, 120, rng),
      calves: randInt(30, 45, rng),
      notes: rng() > 0.6 ? pick(NOTES_POOL, rng) : undefined,
    });
  }
  return entries.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
}

/** Generate session logs. */
function generateSessionLogs(baseSeed: number, count: number): SessionEntry[] {
  const rng = seededRandom(baseSeed + 300);
  const entries: SessionEntry[] = [];
  for (let i = 0; i < count; i++) {
    entries.push({
      id: `sess-${i}`,
      date: addDays(getTodayISO(), -randInt(0, 60, rng)),
      type: pick(SESSION_TYPES, rng),
      duration: pick([30, 45, 60, 75, 90], rng),
      exercises: pickMultiple(EXERCISE_POOL, randInt(4, 8, rng), rng),
      notes: pick(NOTES_POOL, rng),
      rating: randInt(3, 5, rng),
      status: rng() > 0.8 ? 'cancelled' : rng() > 0.85 ? 'no-show' : 'completed',
    });
  }
  return entries.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
}

/** Generate progress photos metadata. */
function generateProgressPhotos(baseSeed: number, count: number): ProgressPhoto[] {
  const rng = seededRandom(baseSeed + 400);
  const labels: ProgressPhoto['label'][] = ['front', 'back', 'side', 'other'];
  const entries: ProgressPhoto[] = [];
  for (let i = 0; i < count; i++) {
    entries.push({
      id: `photo-${i}`,
      date: addDays(getTodayISO(), -randInt(7, 120, rng)),
      url: `/demo/photos/client-${baseSeed}-${i}.jpg`,
      label: pick(labels, rng),
    });
  }
  return entries.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
}

/** Generate a nutrition plan snapshot. */
function generateNutritionPlan(baseSeed: number): NutritionSnapshot | null {
  const rng = seededRandom(baseSeed + 500);
  if (rng() > 0.85) return null; // Some clients have no plan
  const goalTypes: ClientGoal[] = ['lose-fat', 'build-muscle', 'strength', 'endurance', 'maintenance'];
  const goal = pick(goalTypes, rng);
  const dailyCalories = goal === 'lose-fat' ? randInt(1400, 1800, rng)
    : goal === 'build-muscle' ? randInt(2400, 3000, rng)
    : randInt(1800, 2400, rng);
  return {
    plan: goal === 'lose-fat' ? 'Calorie Deficit Protocol' : goal === 'build-muscle' ? 'Lean Mass Protocol' : 'Balanced Maintenance',
    dailyCalories,
    protein: Math.round(dailyCalories * 0.3 / 4),
    carbs: Math.round(dailyCalories * 0.4 / 4),
    fats: Math.round(dailyCalories * 0.3 / 9),
    waterIntake: randInt(2, 4, rng),
    adherence: randInt(65, 98, rng),
  };
}

