/**
 * Generate an array of demo clients with realistic Hong Kong-based data.
 * @param count Number of clients to generate (default: 12)
 */
export function generateClients(count: number = 12): DemoClient[] {
  const clients: DemoClient[] = [];
  const actualCount = Math.min(count, HK_CLIENTS.length);

  for (let i = 0; i < actualCount; i++) {
    const template = HK_CLIENTS[i];
    const rng = seededRandom(i + 1);
    const joinDate = template.joinDate;
    const lastSessDaysAgo = template.status === 'inactive' ? randInt(30, 90, rng)
      : template.status === 'on-hold' ? randInt(14, 45, rng)
      : randInt(0, 10, rng);

    const progress = template.status === 'active' ? randInt(72, 98, rng)
      : template.status === 'on-hold' ? randInt(55, 75, rng)
      : randInt(40, 65, rng);

    const birthYear = randInt(1985, 1998, rng);
    const birthMonth = randInt(1, 12, rng);
    const birthDay = randInt(1, 28, rng);
    const dateOfBirth = `${birthYear}-${String(birthMonth).padStart(2, '0')}-${String(birthDay).padStart(2, '0')}`;

    const bioCount = randInt(2, 5, rng);
    const measCount = randInt(3, 8, rng);
    const sessCount = randInt(5, 20, rng);
    const photoCount = randInt(2, 6, rng);

    const initials = template.name.split(' ').map((n) => n[0]).join('').toUpperCase();
    const sessionsCompleted = randInt(10, 80, rng);
    const lastActive = addDays(getTodayISO(), -randInt(0, lastSessDaysAgo + 5, rng));

    clients.push({
      id: `demo-client-${i}`,
      name: template.name,
      email: template.email,
      status: template.status,
      joinDate,
      lastSession: addDays(getTodayISO(), -lastSessDaysAgo),
      progress,
      phone: template.phone,
      dateOfBirth,
      gender: template.gender,
      height: template.height,
      goal: template.goal,
      notes: pick(NOTES_POOL, rng),
      bioPrints: generateBioPrints(i, bioCount),
      assignedProgram: PROGRAM_NAMES[i % PROGRAM_NAMES.length],
      program: PROGRAM_NAMES[i % PROGRAM_NAMES.length],
      programProgress: progress,
      programHistory: pickMultiple(PROGRAM_NAMES, randInt(1, 3, rng), rng),
      sessionLogs: generateSessionLogs(i, sessCount),
      measurements: generateMeasurements(i, measCount),
      progressPhotos: generateProgressPhotos(i, photoCount),
      nutritionPlan: generateNutritionPlan(i),
      archived: template.status === 'inactive',
      archivedAt: template.status === 'inactive' ? addDays(getTodayISO(), -randInt(15, 60, rng)) : null,
      initials,
      complianceScore: randInt(60, 98, rng),
      sessionsCompleted,
      lastActive,
    });
  }

  return clients;
}

/**
 * Generate demo training sessions scheduled across a number of days.
 * @param days Number of days into the past and future to generate sessions for (default: 30)
 */
export function generateSessions(days: number = 30): DemoSession[] {
  const rng = seededRandom(42);
  const sessions: DemoSession[] = [];
  const clients = HK_CLIENTS.slice(0, 8); // Use first 8 clients for sessions
  let idCounter = 0;

  const today = new Date();
  const startDate = new Date(today);
  startDate.setDate(today.getDate() - days);
  const endDate = new Date(today);
  endDate.setDate(today.getDate() + days);

  for (let d = new Date(startDate); d <= endDate; d.setDate(d.getDate() + 1)) {
    const dateStr = d.toISOString().split('T')[0];
    const numSessions = randInt(1, 5, rng);

    for (let s = 0; s < numSessions; s++) {
      const client = pick(clients, rng);
      const isPast = d < today;
      const status: DemoSession['status'] = isPast
        ? (rng() > 0.85 ? 'cancelled' : rng() > 0.9 ? 'no-show' : 'completed')
        : 'scheduled';
      const time = randomTime(rng);
      const duration = pick([30, 45, 60, 75, 90], rng);
      const [h, m] = time.split(':').map(Number);
      const endH = h + Math.floor((m + duration) / 60);
      const endM = (m + duration) % 60;
      const endTime = `${String(endH).padStart(2, '0')}:${String(endM).padStart(2, '0')}`;

      sessions.push({
        id: `sess-${idCounter++}`,
        clientId: `demo-client-${clients.indexOf(client)}`,
        clientName: client.name,
        date: dateStr,
        time,
        startTime: time,
        endTime,
        duration,
        type: pick(SESSION_TYPES, rng),
        status,
        notes: rng() > 0.7 ? pick(NOTES_POOL, rng) : '',
      });
    }
  }

  return sessions.sort((a, b) => `${a.date}T${a.time}`.localeCompare(`${b.date}T${b.time}`));
}

/**
 * Generate demo alerts/notifications for the trainer dashboard.
 * @param count Number of alerts to generate (default: 8)
 */
export function generateAlerts(count: number = 8): DemoAlert[] {
  const rng = seededRandom(77);
  const alerts: DemoAlert[] = [];
  const categories: DemoAlert['category'][] = ['missed-session', 'goal-risk', 'progress-stall', 'injury', 'general'];
  const severities: DemoAlert['severity'][] = ['low', 'medium', 'high', 'critical'];

  const alertTemplates: Record<DemoAlert['category'], Array<{ title: string; description: string }>> = {
    'missed-session': [
      { title: 'Missed Session', description: 'Client did not show up for scheduled training.' },
      { title: 'No-Show Alert', description: 'Session missed without prior notice.' },
    ],
    'goal-risk': [
      { title: 'Goal At Risk', description: 'Client falling behind on weekly targets.' },
      { title: 'Compliance Drop', description: 'Workout adherence below 60% this week.' },
    ],
    'progress-stall': [
      { title: 'Progress Plateau', description: 'No measurable improvement in 2 weeks.' },
      { title: 'Weight Stagnant', description: 'Body weight unchanged for 3+ weeks.' },
    ],
    'injury': [
      { title: 'Injury Reported', description: 'Client reported discomfort during exercises.' },
      { title: 'Medical Hold', description: 'Recommended pause on lower body training.' },
    ],
    'general': [
      { title: 'Check-in Overdue', description: 'Weekly check-in not completed.' },
      { title: 'Plan Renewal', description: 'Current program ends in 3 days.' },
    ],
  };

  for (let i = 0; i < count; i++) {
    const category = pick(categories, rng);
    const templates = alertTemplates[category];
    const tpl = pick(templates, rng);
    const client = pick(HK_CLIENTS, rng);

    alerts.push({
      id: `alert-${i}`,
      title: tpl.title,
      description: tpl.description,
      severity: pick(severities, rng),
      priority: pick(['low', 'medium', 'high'], rng),
      clientId: `demo-client-${HK_CLIENTS.indexOf(client)}`,
      clientName: client.name,
      createdAt: addDays(getTodayISO(), -randInt(0, 14, rng)),
      resolved: rng() > 0.7,
      category,
      message: tpl.description,
      action: { label: 'View', handler: 'view' },
    });
  }

  return alerts.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
}

