/** Get today's date as ISO string (YYYY-MM-DD). */
export function getTodayISO(): string {
  return new Date().toISOString().split('T')[0];
}

/**
 * Filter sessions for a specific date.
 * @param sessions Array of sessions
 * @param date ISO date string (YYYY-MM-DD)
 */
export function getSessionsForDate(sessions: DemoSession[], date: string): DemoSession[] {
  return sessions.filter((s) => s.date === date);
}

/**
 * Format an ISO date string as a relative time string (e.g., "2 hours ago").
 * @param date ISO date string
 */
export function formatRelativeTime(date: string): string {
  const now = Date.now();
  const then = new Date(date).getTime();
  const diffMs = now - then;

  if (isNaN(diffMs)) return 'unknown';

  const seconds = Math.floor(diffMs / 1000);
  const minutes = Math.floor(seconds / 60);
  const hours = Math.floor(minutes / 60);
  const days = Math.floor(hours / 24);
  const weeks = Math.floor(days / 7);
  const months = Math.floor(days / 30);

  if (seconds < 10) return 'just now';
  if (seconds < 60) return `${seconds} seconds ago`;
  if (minutes < 2) return '1 minute ago';
  if (minutes < 60) return `${minutes} minutes ago`;
  if (hours < 2) return '1 hour ago';
  if (hours < 24) return `${hours} hours ago`;
  if (days < 2) return 'yesterday';
  if (days < 7) return `${days} days ago`;
  if (weeks < 5) return `${weeks} week${weeks > 1 ? 's' : ''} ago`;
  if (months < 12) return `${months} month${months > 1 ? 's' : ''} ago`;
  return new Date(date).toLocaleDateString('en-GB');
}

/**
 * Format an ISO date string to a readable timestamp.
 * @param date ISO date string
 */
export function formatTimestamp(date: string): string {
  const d = new Date(date);
  if (isNaN(d.getTime())) return 'Invalid date';
  return d.toLocaleString('en-GB', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
}

