import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import type { StateCreator } from 'zustand';

/* ------------------------------------------------------------------ */
/*  Primitive types                                                    */
/* ------------------------------------------------------------------ */

export type EventTypeCategory = 'session' | 'assessment' | 'follow-up' | 'birthday' | 'reminder' | 'unavailable' | 'event' | 'Meeting' | 'Seminar' | 'Holiday' | 'Other';
export type RecurrenceType = 'none' | 'daily' | 'weekly' | 'biweekly' | 'bi-weekly' | 'monthly';
export type PriorityLevel = 'low' | 'medium' | 'high';
export type SessionType = 'pt' | 'group' | 'online' | 'assessment' | 'strength' | 'cardio' | 'recovery' | 'other';
export type SessionStatus = 'upcoming' | 'completed' | 'cancelled' | 'no-show' | 'confirmed' | 'in-progress' | 'pending';

/* ------------------------------------------------------------------ */
/*  Interfaces                                                         */
/* ------------------------------------------------------------------ */

export interface CalendarEvent {
  id: string;
  title: string;
  date: string; // YYYY-MM-DD
  startTime: string; // HH:MM
  endTime: string; // HH:MM
  duration: number;
  type: EventTypeCategory;
  status: SessionStatus;
  clientId?: string;
  clientName?: string;
  clientColor?: string;
  color?: string;
  description?: string;
  notes?: string;
  eventCategory?: string;
  isRecurring: boolean;
  seriesId?: string | null;
  programDay?: string;
  notifyBefore?: boolean;
  createdAt: string;
  updatedAt: string;
}

export interface Session {
  id: string;
  title: string;
  clientId: string;
  clientName: string;
  date: string;
  startTime: string;
  endTime: string;
  duration: number;
  type: SessionType;
  status: SessionStatus;
  notes?: string;
  isRecurring: boolean;
  seriesId?: string | null;
  clientColor?: string;
  programId?: string;
  programDay?: string;
  trainerRating?: number;
  createdAt: string;
  updatedAt: string;
}

export interface TodoItem {
  id: string;
  title: string;
  text?: string;
  completed: boolean;
  priority: PriorityLevel;
  dueDate?: string;
  createdAt: string;
}

export interface Reminder {
  id: string;
  title: string;
  time: string;
  date: string;
  startTime?: string;
  endTime?: string;
  color?: string;
  description?: string;
  priority: PriorityLevel;
  completed: boolean;
}

export interface BlockedTime {
  id: string;
  date: string;
  startTime: string;
  endTime: string;
  reason?: string;
  label?: string;
  color?: string;
  recurrence?: string;
  recurrenceDays?: string[];
  endDate?: string | null;
}

/* ------------------------------------------------------------------ */
/*  State & Actions                                                    */
/* ------------------------------------------------------------------ */

interface CalendarState {
  /* -- state -- */
  events: CalendarEvent[];
  sessions: Session[];
  selectedDate: string;
  viewMode: 'week' | 'month' | 'day' | 'agenda';
  todos: TodoItem[];
  reminders: Reminder[];
  blockedTimes: BlockedTime[];

  /* -- computed -- */
  unreadCount: number;

  /* -- CalendarEvent actions -- */
  addCalendarEvent: (event: Partial<Omit<CalendarEvent, 'id' | 'createdAt' | 'updatedAt'>>) => void;
  updateEvent: (id: string, data: Partial<CalendarEvent>) => void;
  deleteEvent: (id: string) => void;
  moveEvent: (eventId: string, newDate: string) => void;

  /* -- Session actions -- */
  addSession: (session: Omit<Session, 'id' | 'createdAt' | 'updatedAt'>) => void;
  updateSession: (id: string, data: Partial<Session>) => void;
  deleteSession: (id: string) => void;
  checkConflict: (date: string, startTime: string, endTime: string, excludeId?: string) => boolean;
  createRecurringSeries: (base: Partial<Session>, recurrence: RecurrenceType, count: number) => void;

  /* -- UI state actions -- */
  setSelectedDate: (date: string) => void;
  setViewMode: (mode: 'week' | 'month' | 'day' | 'agenda') => void;

  /* -- BlockedTime actions -- */
  addBlockedTime: (block: Omit<BlockedTime, 'id'>) => void;

  /* -- Reminder actions -- */
  addReminder: (reminder: Partial<Omit<Reminder, 'id'>>) => void;

  /* -- Todo actions -- */
  addTodo: (todo: Partial<Omit<TodoItem, 'id' | 'createdAt'>> & Pick<TodoItem, 'title'>) => void;
  toggleTodo: (id: string) => void;
  deleteTodo: (id: string) => void;

  /* -- Birthday action -- */
  addBirthday: (event: Partial<Omit<CalendarEvent, 'id' | 'createdAt' | 'updatedAt' | 'type' | 'status' | 'duration' | 'endTime'>>) => void;
}

/* ------------------------------------------------------------------ */
/*  Helpers                                                            */
/* ------------------------------------------------------------------ */

function generateId(prefix: string): string {
  return `${prefix}_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;
}

function timeToMinutes(time: string): number {
  const [h, m] = time.split(':').map(Number);
  return h * 60 + m;
}

function addDays(dateStr: string, days: number): string {
  const d = new Date(dateStr + 'T00:00:00');
  d.setDate(d.getDate() + days);
  return d.toISOString().split('T')[0];
}

function getRecurrenceInterval(recurrence: RecurrenceType): number {
  switch (recurrence) {
    case 'daily': return 1;
    case 'weekly': return 7;
    case 'biweekly': return 14;
    case 'bi-weekly': return 14;
    case 'monthly': return 30;
    default: return 0;
  }
}

/* ------------------------------------------------------------------ */
/*  Store factory                                                      */
/* ------------------------------------------------------------------ */

const calendarStoreFactory: StateCreator<CalendarState> = (set, get) => ({
  /* -- initial state -- */
  events: [],
  sessions: [],
  selectedDate: new Date().toISOString().split('T')[0],
  viewMode: 'week',
  todos: [],
  reminders: [],
  blockedTimes: [],

  /* -- computed -- */
  get unreadCount() {
    return get().reminders.filter((r) => !r.completed).length;
  },

  /* -- CalendarEvent actions -- */
  addCalendarEvent: (event): void => {
    const now = new Date().toISOString();
    const newEvent: CalendarEvent = {
      ...event,
      id: generateId('evt'),
      createdAt: now,
      updatedAt: now,
    };
    set((state) => ({ events: [...state.events, newEvent] }));
  },

  updateEvent: (id, data): void => {
    const now = new Date().toISOString();
    set((state) => ({
      events: state.events.map((e) =>
        e.id === id ? { ...e, ...data, updatedAt: now } : e
      ),
    }));
  },

  deleteEvent: (id): void => {
    set((state) => ({
      events: state.events.filter((e) => e.id !== id),
    }));
  },

  moveEvent: (eventId, newDate): void => {
    const now = new Date().toISOString();
    set((state) => ({
      events: state.events.map((e) =>
        e.id === eventId ? { ...e, date: newDate, updatedAt: now } : e
      ),
    }));
  },

  /* -- Session actions -- */
  addSession: (session): void => {
    const now = new Date().toISOString();
    const newSession: Session = {
      ...session,
      id: generateId('ses'),
      createdAt: now,
      updatedAt: now,
    };
    set((state) => ({ sessions: [...state.sessions, newSession] }));
  },

  updateSession: (id, data): void => {
    const now = new Date().toISOString();
    set((state) => ({
      sessions: state.sessions.map((s) =>
        s.id === id ? { ...s, ...data, updatedAt: now } : s
      ),
    }));
  },

  deleteSession: (id): void => {
    set((state) => ({
      sessions: state.sessions.filter((s) => s.id !== id),
    }));
  },

  checkConflict: (date, startTime, endTime, excludeId?): boolean => {
    const state = get();
    const startMin = timeToMinutes(startTime);
    const endMin = timeToMinutes(endTime);

    return state.sessions.some((s) => {
      if (s.id === excludeId) return false;
      if (s.date !== date) return false;
      const sStart = timeToMinutes(s.startTime);
      const sEnd = timeToMinutes(s.endTime);
      return startMin < sEnd && endMin > sStart;
    });
  },

  createRecurringSeries: (base, recurrence, count): void => {
    const interval = getRecurrenceInterval(recurrence);
    if (interval === 0) return;

    const now = new Date().toISOString();
    const seriesId = generateId('rec');
    const newSessions: Session[] = [];

    for (let i = 0; i < count; i++) {
      const date = addDays(base.date ?? now.split('T')[0], i * interval);
      const session: Session = {
        id: generateId('ses'),
        title: base.title ?? 'Recurring Session',
        clientId: base.clientId ?? '',
        clientName: base.clientName ?? '',
        date,
        startTime: base.startTime ?? '09:00',
        endTime: base.endTime ?? '10:00',
        duration: base.duration ?? 60,
        type: base.type ?? 'pt',
        status: base.status ?? 'upcoming',
        notes: base.notes,
        isRecurring: true,
        seriesId,
        createdAt: now,
        updatedAt: now,
      };
      newSessions.push(session);
    }

    set((state) => ({
      sessions: [...state.sessions, ...newSessions],
    }));
  },

  /* -- UI state actions -- */
  setSelectedDate: (date): void => {
    set({ selectedDate: date });
  },

  setViewMode: (mode): void => {
    set({ viewMode: mode });
  },

  /* -- BlockedTime actions -- */
  addBlockedTime: (block): void => {
    const newBlock: BlockedTime = {
      ...block,
      id: generateId('blk'),
    };
    set((state) => ({
      blockedTimes: [...state.blockedTimes, newBlock],
    }));
  },

  /* -- Reminder actions -- */
  addReminder: (reminder): void => {
    const newReminder: Reminder = {
      ...reminder,
      id: generateId('rem'),
    };
    set((state) => ({
      reminders: [...state.reminders, newReminder],
    }));
  },

  /* -- Todo actions -- */
  addTodo: (todo): void => {
    const newTodo: TodoItem = {
      title: todo.title ?? '',
      text: todo.text,
      completed: todo.completed ?? false,
      priority: todo.priority ?? 'medium',
      dueDate: todo.dueDate,
      id: generateId('todo'),
      createdAt: new Date().toISOString(),
    };
    set((state) => ({
      todos: [...state.todos, newTodo],
    }));
  },

  toggleTodo: (id): void => {
    set((state) => ({
      todos: state.todos.map((t) =>
        t.id === id ? { ...t, completed: !t.completed } : t
      ),
    }));
  },

  deleteTodo: (id): void => {
    set((state) => ({
      todos: state.todos.filter((t) => t.id !== id),
    }));
  },

  /* -- Birthday action -- */
  addBirthday: (event): void => {
    const now = new Date().toISOString();
    const newEvent: CalendarEvent = {
      ...event,
      type: 'birthday',
      status: 'upcoming',
      duration: 1439,
      endTime: '23:59',
      id: generateId('evt'),
      createdAt: now,
      updatedAt: now,
    };
    set((state) => ({ events: [...state.events, newEvent] }));
  },
});

