import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import type { StateCreator } from 'zustand';
import type { ProgramPhase, DayPlan, BlockFormat, TrainingMethod } from '@/types/program';

/* ------------------------------------------------------------------ */
/*  Re-exported / local primitive types                                */
/* ------------------------------------------------------------------ */

export type GoalType =
  | 'lose-fat'
  | 'build-muscle'
  | 'strength'
  | 'endurance'
  | 'maintenance'
  | 'recomposition'
  | 'fat-loss'
  | 'hypertrophy'
  | 'powerlifting'
  | 'bodybuilding'
  | 'general-fitness';

export type DifficultyLevel = 'beginner' | 'intermediate' | 'advanced' | 'elite';
export type ProgramPhaseName = 'foundation' | 'progression' | 'intensification' | 'deload' | 'peak';

export type MuscleGroup =
  | 'chest'
  | 'back'
  | 'shoulders'
  | 'biceps'
  | 'triceps'
  | 'legs'
  | 'glutes'
  | 'core'
  | 'cardio'
  | 'full-body';

export type EquipmentType =
  | 'barbell'
  | 'dumbbell'
  | 'cable'
  | 'machine'
  | 'bodyweight'
  | 'kettlebell'
  | 'band'
  | 'plate'
  | 'medicine-ball'
  | 'none'
  | 'Custom';

/* ------------------------------------------------------------------ */
/*  Exercise library types                                             */
/* ------------------------------------------------------------------ */

export interface ExerciseDefinition {
  id: string;
  name: string;
  category: MuscleGroup;
  equipment: EquipmentType;
  description?: string;
  instructions?: string[];
  tips?: string[];
  primaryMuscles: string[];
  secondaryMuscles?: string[];
  muscleGroup?: string;
  muscle?: string;
  muscleGroups?: string[];
  difficulty?: string;
  type?: string;
  videoUrl?: string;
  imageUrl?: string;
}

/* ------------------------------------------------------------------ */
/*  Program types                                                      */
/* ------------------------------------------------------------------ */

export interface BlockExercise {
  exerciseId?: string;
  exerciseName?: string;
  name?: string;
  sets: number;
  reps: string;
  restSeconds?: number;
  rest?: string;
  tempo?: string;
  rpe?: number;
  notes?: string;
  order: number;
  id?: string;
  exerciseGroup?: string;
  weight?: string;
  supersetWith?: string | null;
  isSubstituted?: boolean;
  originalExerciseId?: string | null;
}

export interface ProgramExerciseBlock {
  id: string;
  name: string;
  format?: BlockFormat;
  focus?: string;
  dayOfWeek?: string;
  dayIndex?: number;
  exercises: BlockExercise[];
  restBetweenRounds?: string;
  restBetweenExercises?: string;
  rounds?: number;
  order: number;
}

export interface Program {
  id: string;
  name: string;
  description?: string;
  goal: GoalType;
  method?: TrainingMethod;
  methodType?: string;
  difficulty: DifficultyLevel;
  durationWeeks: number;
  duration?: string | number;
  sessionsPerWeek: number;
  frequency?: number;
  blocks: ProgramExerciseBlock[];
  assignedClientIds: string[];
  clientId?: string;
  clientName?: string;
  phase: ProgramPhaseName;
  phases?: ProgramPhase[];
  weeklySplit: DayPlan[] | string[];
  tags?: string[];
  equipmentRequired?: string[];
  progressionRules?: string[];
  estimatedTimePerSession?: number;
  totalVolume?: number;
  createdAt: string;
  updatedAt: string;
}

/* ------------------------------------------------------------------ */
/*  Wizard-local types (mutable draft state)                           */
/* ------------------------------------------------------------------ */

export interface WizardExercise {
  id: string;
  exerciseId: string;
  exerciseName: string;
  name?: string;
  sets: number;
  reps: string;
  restSeconds: number;
  rest?: string;
  tempo?: string;
  rpe?: number;
  notes?: string;
  order: number;
  weight?: string;
  supersetWith?: string | null;
  isSubstituted?: boolean;
  originalExerciseId?: string | null;
  muscleGroup?: string;
  difficulty?: string;
  type?: string;
}

export interface WizardBlock {
  id: string;
  name: string;
  format?: BlockFormat;
  focus?: string;
  dayOfWeek?: string;
  dayIndex?: number;
  exercises: WizardExercise[];
  restBetweenRounds?: string;
  restBetweenExercises?: string;
  rounds?: number;
  order: number;
}

export interface WizardPhase {
  id: string;
  name: string;
  description?: string;
  order: number;
  weekStart: number;
  weekEnd: number;
  focus: string;
  intensityTarget?: string;
  volumeTarget?: string;
  exercises?: any[];
}

/* ------------------------------------------------------------------ */
/*  State & Actions                                                    */
/* ------------------------------------------------------------------ */

interface ProgramState {
  /* -- state: programs & exercise library -- */
  programs: Program[];
  exercises: ExerciseDefinition[];

  /* -- state: wizard draft -- */
  wizard: {
    currentStep: number;
    selectedGoal: GoalType | null;
    selectedMethod: string | null;
    selectedMethodType: string | null;
    selectedClientId: string | null;
    selectedClientName: string | null;
    difficulty: DifficultyLevel | null;
    programName: string;
    description: string;
    tags: string[];
    phases: WizardPhase[];
    wizardBlocks: WizardBlock[];
    weeklySplit: DayPlan[];
  };

  /* -- Program CRUD actions -- */
  addProgram: (program: Program | Omit<Program, 'id' | 'createdAt' | 'updatedAt'>) => string;
  updateProgram: (id: string, data: Partial<Program>) => void;
  deleteProgram: (id: string) => void;

  /* -- Wizard step actions -- */
  setWizardStep: (step: number) => void;
  setWizardGoal: (goal: GoalType | null) => void;
  setWizardMethod: (method: string | null) => void;
  setWizardMethodType: (methodType: string | null) => void;
  setWizardDifficulty: (difficulty: DifficultyLevel | null) => void;
  setWizardClient: (clientId: string | null, clientName?: string) => void;
  setWeeklySplit: (split: DayPlan[] | string[]) => void;
  setWeeklySplitDay: (dayIndex: number, day: string) => void;
  saveWizardDraft: () => void;
  clearWizard: () => void;
  getMethodsForGoal: (goal: GoalType) => MethodOption[];

  /* -- Phase actions -- */
  addPhase: (phase: Omit<WizardPhase, 'id'>) => void;
  removePhase: (phaseId: string) => void;
  updatePhase: (phaseId: string, data: Partial<WizardPhase>) => void;

  /* -- Auto-populate actions -- */
  autoPopulateExercises: (method?: string, goal?: GoalType) => any[];

  /* -- Block actions -- */
  addBlock: (block: WizardBlock) => void;
  removeBlock: (blockId: string) => void;
  updateBlock: (blockId: string, data: Partial<WizardBlock>) => void;
  autoAssignGroups: () => void;
  autoPopulateBlocks: () => void;

  /* -- Exercise-in-block actions -- */
  addExerciseToBlock: (blockId: string, exercise: WizardExercise) => void;
  removeExerciseFromBlock: (blockId: string, exerciseId: string) => void;
  updateBlockExercise: (blockId: string, exerciseId: string, data: Partial<WizardExercise>) => void;
  reorderExercisesInBlock: (blockId: string, oldIndex: number, newIndex: number) => void;
  reorderBlocks: (oldIndex: number, newIndex: number) => void;
}

export interface MethodOption {
  id: string;
  name: string;
  shortName?: string;
  description: string;
  goals: GoalType[];
  goal?: GoalType;
  difficulty: string;
  estimatedWeeks: number;
  frequency?: string;
  duration?: string;
  equipment?: string;
}

/* ------------------------------------------------------------------ */
/*  Helpers                                                            */
/* ------------------------------------------------------------------ */

function generateId(prefix: string): string {
  return `${prefix}_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;
}

function createTimestamp(): string {
  return new Date().toISOString();
}

const METHOD_OPTIONS: MethodOption[] = [
  { id: 'm1', name: 'Straight Sets', description: 'Traditional sets with full rest between', goals: ['strength', 'powerlifting', 'maintenance'], difficulty: 'beginner', estimatedWeeks: 8 },
  { id: 'm2', name: 'Supersets', description: 'Pair exercises back-to-back', goals: ['build-muscle', 'hypertrophy', 'bodybuilding'], difficulty: 'intermediate', estimatedWeeks: 6 },
  { id: 'm3', name: 'Circuit Training', description: 'Continuous movement through stations', goals: ['lose-fat', 'fat-loss', 'endurance', 'general-fitness'], difficulty: 'intermediate', estimatedWeeks: 6 },
  { id: 'm4', name: 'HIIT', description: 'High intensity interval training', goals: ['lose-fat', 'fat-loss', 'endurance'], difficulty: 'advanced', estimatedWeeks: 4 },
  { id: 'm5', name: 'Periodized', description: 'Structured loading phases', goals: ['strength', 'powerlifting', 'build-muscle', 'hypertrophy'], difficulty: 'advanced', estimatedWeeks: 12 },
  { id: 'm6', name: 'Pyramid', description: 'Ascending/descending weight scheme', goals: ['build-muscle', 'hypertrophy', 'bodybuilding'], difficulty: 'intermediate', estimatedWeeks: 8 },
  { id: 'm7', name: 'Dropsets', description: 'Reduce weight and continue to failure', goals: ['build-muscle', 'hypertrophy', 'bodybuilding'], difficulty: 'advanced', estimatedWeeks: 4 },
  { id: 'm8', name: 'German Volume', description: '10 sets of 10 reps', goals: ['build-muscle', 'hypertrophy'], difficulty: 'intermediate', estimatedWeeks: 6 },
];

function getMethodsForGoalFn(goal: GoalType): MethodOption[] {
  return METHOD_OPTIONS.filter((m) => m.goals.includes(goal));
}

