/* ------------------------------------------------------------------ */
/*  Store factory                                                      */
/* ------------------------------------------------------------------ */

const programStoreFactory: StateCreator<ProgramState> = (set, get) => ({
  /* -- initial state -- */
  programs: [],
  exercises: createExerciseLibrary(),

  wizard: {
    currentStep: 0,
    selectedGoal: null,
    selectedMethod: null,
    selectedMethodType: null,
    selectedClientId: null,
    selectedClientName: null,
    difficulty: null,
    programName: '',
    description: '',
    tags: [],
    phases: [],
    wizardBlocks: [],
    weeklySplit: [...DEFAULT_WEEKLY_SPLIT],
  },

  /* -- addProgram -- */
  addProgram: (program): string => {
    const now = createTimestamp();
    const id = generateId('prg');
    const newProgram: Program = {
      ...program,
      id,
      createdAt: now,
      updatedAt: now,
    };
    set((state) => ({
      programs: [...state.programs, newProgram],
    }));
    return id;
  },

  /* -- updateProgram -- */
  updateProgram: (id, data): void => {
    const now = createTimestamp();
    set((state) => ({
      programs: state.programs.map((p) =>
        p.id === id ? { ...p, ...data, updatedAt: now } : p
      ),
    }));
  },

  /* -- deleteProgram -- */
  deleteProgram: (id): void => {
    set((state) => ({
      programs: state.programs.filter((p) => p.id !== id),
    }));
  },

  /* -- setWizardStep -- */
  setWizardStep: (step): void => {
    set((state) => ({
      wizard: { ...state.wizard, currentStep: step },
    }));
  },

  /* -- setWizardGoal -- */
  setWizardGoal: (goal): void => {
    set((state) => ({
      wizard: { ...state.wizard, selectedGoal: goal, selectedMethod: null, selectedMethodType: null },
    }));
  },

  /* -- setWizardMethod -- */
  setWizardMethod: (method): void => {
    set((state) => ({
      wizard: { ...state.wizard, selectedMethod: method },
    }));
  },

  /* -- setWizardMethodType -- */
  setWizardMethodType: (methodType): void => {
    set((state) => ({
      wizard: { ...state.wizard, selectedMethodType: methodType },
    }));
  },

  /* -- setWizardDifficulty -- */
  setWizardDifficulty: (difficulty): void => {
    set((state) => ({
      wizard: { ...state.wizard, difficulty },
    }));
  },

  /* -- setWizardClient -- */
  setWizardClient: (clientId, clientName): void => {
    set((state) => ({
      wizard: {
        ...state.wizard,
        selectedClientId: clientId,
        selectedClientName: clientName ?? state.wizard.selectedClientName,
      },
    }));
  },

  /* -- setWeeklySplit -- */
  setWeeklySplit: (split: string[] | DayPlan[]): void => {
    set((state) => ({
      wizard: { ...state.wizard, weeklySplit: split as (string | DayPlan)[] },
    }));
  },

  /* -- setWeeklySplitDay -- */
  setWeeklySplitDay: (dayIndex, day): void => {
    set((state) => {
      const newSplit = [...state.wizard.weeklySplit] as string[];
      if (dayIndex >= 0 && dayIndex < newSplit.length) {
        newSplit[dayIndex] = day;
      }
      return { wizard: { ...state.wizard, weeklySplit: newSplit as (string | DayPlan)[] } };
    });
  },

  /* -- getMethodsForGoal -- */
  getMethodsForGoal: (goal): MethodOption[] => {
    return getMethodsForGoalFn(goal);
  },

  /* -- addPhase -- */
  addPhase: (phase): void => {
    const newPhase: WizardPhase = {
      ...phase,
      id: generateId('phase'),
    };
    set((state) => ({
      wizard: {
        ...state.wizard,
        phases: [...state.wizard.phases, newPhase],
      },
    }));
  },

  /* -- removePhase -- */
  removePhase: (phaseId): void => {
    set((state) => ({
      wizard: {
        ...state.wizard,
        phases: state.wizard.phases.filter((p) => p.id !== phaseId),
      },
    }));
  },

  /* -- updatePhase -- */
  updatePhase: (phaseId, data): void => {
    set((state) => ({
      wizard: {
        ...state.wizard,
        phases: state.wizard.phases.map((p) =>
          p.id === phaseId ? { ...p, ...data } : p
        ),
      },
    }));
  },

  /* -- saveWizardDraft -- */
  saveWizardDraft: (): void => {
    const state = get();
    const { wizard } = state;
    if (!wizard.selectedGoal || !wizard.difficulty) return;

    const now = createTimestamp();
    const id = generateId('prg');

    const blocks: ProgramExerciseBlock[] = wizard.wizardBlocks.map((wb) => ({
      id: wb.id,
      name: wb.name,
      format: wb.format,
      focus: wb.focus,
      dayOfWeek: wb.dayOfWeek,
      dayIndex: wb.dayIndex,
      order: wb.order,
      exercises: wb.exercises.map((we) => ({
        id: we.id,
        exerciseId: we.exerciseId,
        exerciseName: we.exerciseName,
        name: we.name,
        sets: we.sets,
        reps: we.reps,
        restSeconds: we.restSeconds,
        rest: we.rest,
        tempo: we.tempo,
        rpe: we.rpe,
        notes: we.notes,
        order: we.order,
        exerciseGroup: we.muscleGroup,
        weight: we.weight,
        supersetWith: we.supersetWith,
        isSubstituted: we.isSubstituted,
        originalExerciseId: we.originalExerciseId,
      })),
      restBetweenRounds: wb.restBetweenRounds,
      restBetweenExercises: wb.restBetweenExercises,
      rounds: wb.rounds,
    }));

    const newProgram: Program = {
      id,
      name: wizard.programName || (wizard.selectedMethod
        ? `${wizard.selectedMethod} — ${wizard.selectedClientName ?? 'Unnamed'}`
        : `Program — ${wizard.selectedGoal}`),
      goal: wizard.selectedGoal,
      method: wizard.selectedMethodType as TrainingMethod ?? undefined,
      methodType: wizard.selectedMethodType ?? undefined,
      difficulty: wizard.difficulty,
      durationWeeks: 4,
      duration: '4 weeks',
      sessionsPerWeek: Array.isArray(wizard.weeklySplit)
        ? wizard.weeklySplit.filter((s) => typeof s === 'string' ? !s.toLowerCase().includes('rest') : !s.isRestDay).length
        : 4,
      frequency: Array.isArray(wizard.weeklySplit) ? wizard.weeklySplit.length : 4,
      blocks,
      assignedClientIds: wizard.selectedClientId ? [wizard.selectedClientId] : [],
      clientId: wizard.selectedClientId ?? undefined,
      clientName: wizard.selectedClientName ?? undefined,
      phase: 'foundation',
      phases: wizard.phases.map((wp) => ({
        id: wp.id,
        name: wp.name,
        weekStart: wp.weekStart,
        weekEnd: wp.weekEnd,
        focus: wp.focus,
        intensityTarget: wp.intensityTarget,
        volumeTarget: wp.volumeTarget,
        exercises: wp.exercises ?? [],
      })),
      weeklySplit: wizard.weeklySplit,
      createdAt: now,
      updatedAt: now,
    };

    set((s) => ({
      programs: [...s.programs, newProgram],
    }));
  },

  /* -- clearWizard -- */
  clearWizard: (): void => {
    set({
      wizard: {
        currentStep: 0,
        selectedGoal: null,
        selectedMethod: null,
        selectedMethodType: null,
        selectedClientId: null,
        selectedClientName: null,
        difficulty: null,
        programName: '',
        description: '',
        tags: [],
        phases: [],
        wizardBlocks: [],
        weeklySplit: [...DEFAULT_WEEKLY_SPLIT],
      },
    });
  },

  /* -- autoPopulateExercises -- */
  autoPopulateExercises: (method?: string, goal?: GoalType): any[] => {
    const state = get();
    const { wizard, exercises } = state;
    if (exercises.length === 0) return [];

    const effectiveGoal = goal || wizard.selectedGoal;
    const effectiveMethod = method || wizard.selectedMethod;
    const difficulty = wizard.difficulty ?? 'intermediate';

    // Filter exercises by goal relevance
    let filtered = [...exercises];
    if (effectiveGoal === 'fat-loss' || effectiveGoal === 'lose-fat') {
      filtered = filtered.filter((e) => e.category === 'cardio' || e.category === 'full-body' || e.category === 'legs');
    } else if (effectiveGoal === 'strength' || effectiveGoal === 'powerlifting') {
      filtered = filtered.filter((e) =>
        ['back', 'legs', 'chest', 'shoulders'].includes(e.category)
      );
    } else if (effectiveGoal === 'hypertrophy' || effectiveGoal === 'bodybuilding' || effectiveGoal === 'build-muscle') {
      // all categories OK for hypertrophy
    } else if (effectiveGoal === 'endurance') {
      filtered = filtered.filter((e) => e.category === 'cardio' || e.category === 'legs' || e.category === 'full-body');
    }

    // If filtering left too few, fall back to all
    if (filtered.length < 6) {
      filtered = [...exercises];
    }

    // Build wizard exercises from filtered
    const allWizardExercises: WizardExercise[] = filtered.slice(0, 20).map((ex, idx) => ({
      id: generateId('we'),
      exerciseId: ex.id,
      exerciseName: ex.name,
      sets: difficulty === 'beginner' ? 3 : difficulty === 'advanced' || difficulty === 'elite' ? 4 : 3,
      reps: effectiveGoal === 'strength' || effectiveGoal === 'powerlifting' ? '3-5' : effectiveGoal === 'endurance' ? '12-15' : '8-12',
      restSeconds: effectiveGoal === 'fat-loss' || effectiveGoal === 'lose-fat' || effectiveGoal === 'endurance' ? 45 : 90,
      tempo: '2-0-2',
      rpe: difficulty === 'beginner' ? 7 : 8,
      order: idx,
    }));

    // Auto-populate exercises into existing blocks
    set((s) => {
      const updatedBlocks = s.wizard.wizardBlocks.map((block) => {
        if (block.exercises.length > 0) return block; // don't overwrite existing

        // Pick 4-6 exercises based on block focus
        const focusKeywords = (block.focus ?? '').toLowerCase().split(/[\s&\-–]+/);
        const blockExercises = filtered
          .filter((ex) => {
            const exName = ex.name.toLowerCase();
            const exCat = ex.category.toLowerCase();
            return focusKeywords.some((fk) => exName.includes(fk) || exCat.includes(fk));
          })
          .slice(0, 5);

        // Fallback: just pick from filtered list
        const selected = blockExercises.length > 0 ? blockExercises : filtered.slice(0, 5);

        const wizardExercises: WizardExercise[] = selected.map((ex, idx) => ({
          id: generateId('we'),
          exerciseId: ex.id,
          exerciseName: ex.name,
          sets: difficulty === 'beginner' ? 3 : difficulty === 'advanced' || difficulty === 'elite' ? 4 : 3,
          reps: effectiveGoal === 'strength' || effectiveGoal === 'powerlifting' ? '3-5' : effectiveGoal === 'endurance' ? '12-15' : '8-12',
          restSeconds: effectiveGoal === 'fat-loss' || effectiveGoal === 'lose-fat' || effectiveGoal === 'endurance' ? 45 : 90,
          tempo: '2-0-2',
          rpe: difficulty === 'beginner' ? 7 : 8,
          order: idx,
        }));

        return { ...block, exercises: wizardExercises };
      });

      return {
        wizard: { ...s.wizard, wizardBlocks: updatedBlocks },
      };
    });

    return allWizardExercises;
  },

  /* -- addBlock -- */
  addBlock: (block): void => {
    set((state) => ({
      wizard: {
        ...state.wizard,
        wizardBlocks: [...state.wizard.wizardBlocks, block],
      },
    }));
  },

  /* -- removeBlock -- */
  removeBlock: (blockId): void => {
    set((state) => ({
      wizard: {
        ...state.wizard,
        wizardBlocks: state.wizard.wizardBlocks.filter((b) => b.id !== blockId),
      },
    }));
  },

  /* -- updateBlock -- */
  updateBlock: (blockId, data): void => {
    set((state) => ({
      wizard: {
        ...state.wizard,
        wizardBlocks: state.wizard.wizardBlocks.map((b) =>
          b.id === blockId ? { ...b, ...data } : b
        ),
      },
    }));
  },

  /* -- autoAssignGroups -- */
  autoAssignGroups: (): void => {
    const state = get();
    const { exercises, wizard } = state;
    if (wizard.wizardBlocks.length === 0) return;

    const blocks = wizard.wizardBlocks.map((block) => {
      if (block.exercises.length > 0) return block;

      const focusKeywords = (block.focus ?? '').toLowerCase().split(/[\s&\-–]+/);
      const matched = exercises.filter((ex) =>
        focusKeywords.some(
          (fk) =>
            ex.category.toLowerCase().includes(fk) ||
            ex.name.toLowerCase().includes(fk) ||
            (ex.primaryMuscles ?? []).some((m) => m.toLowerCase().includes(fk))
        )
      );

      const selected = matched.length > 0 ? matched.slice(0, 5) : exercises.slice(0, 5);
      const wizardExercises: WizardExercise[] = selected.map((ex, idx) => ({
        id: generateId('we'),
        exerciseId: ex.id,
        exerciseName: ex.name,
        sets: 3,
        reps: '8-12',
        restSeconds: 60,
        order: idx,
      }));

      return { ...block, exercises: wizardExercises };
    });

    set((s) => ({
      wizard: { ...s.wizard, wizardBlocks: blocks },
    }));
  },

  /* -- autoPopulateBlocks -- */
  autoPopulateBlocks: (): void => {
    const state = get();
    const { wizard, exercises } = state;

    const splitDays = Array.isArray(wizard.weeklySplit)
      ? wizard.weeklySplit.filter((s) => typeof s === 'string' ? !s.toLowerCase().includes('rest') : !s.isRestDay)
      : [];
    if (splitDays.length === 0) return;

    const blocks: WizardBlock[] = splitDays.map((dayLabel, idx) => {
      const label = typeof dayLabel === 'string' ? dayLabel : dayLabel.dayOfWeek ?? 'Monday';
      const focus = label.split(/[–\-]/).pop()?.trim() ?? 'General';
      const blockId = generateId('wb');

      // Match exercises to focus
      const focusKeywords = focus.toLowerCase().split(/[\s&\-–]+/);
      const matched = exercises.filter((ex) =>
        focusKeywords.some(
          (fk) =>
            ex.category.toLowerCase().includes(fk) ||
            ex.name.toLowerCase().includes(fk) ||
            (ex.primaryMuscles ?? []).some((m) => m.toLowerCase().includes(fk))
        )
      );

      const selected = matched.length > 0 ? matched.slice(0, 6) : exercises.slice(idx * 6, idx * 6 + 6);
      const wizardExercises: WizardExercise[] = selected.map((ex, eIdx) => ({
        id: generateId('we'),
        exerciseId: ex.id,
        exerciseName: ex.name,
        sets: 3,
        reps: '8-12',
        restSeconds: 60,
        order: eIdx,
      }));

      return {
        id: blockId,
        name: label,
        dayOfWeek: typeof dayLabel === 'string' ? dayLabel.split(/[–\-]/)[0]?.trim() ?? 'Monday' : dayLabel.dayOfWeek ?? 'Monday',
        focus,
        order: idx,
        exercises: wizardExercises,
      };
    });

    set((s) => ({
      wizard: { ...s.wizard, wizardBlocks: blocks },
    }));
  },

  /* -- addExerciseToBlock -- */
  addExerciseToBlock: (blockId, exercise): void => {
    set((state) => ({
      wizard: {
        ...state.wizard,
        wizardBlocks: state.wizard.wizardBlocks.map((b) =>
          b.id === blockId
            ? { ...b, exercises: [...b.exercises, { ...exercise, order: b.exercises.length }] }
            : b
        ),
      },
    }));
  },

  /* -- removeExerciseFromBlock -- */
  removeExerciseFromBlock: (blockId, exerciseId): void => {
    set((state) => ({
      wizard: {
        ...state.wizard,
        wizardBlocks: state.wizard.wizardBlocks.map((b) =>
          b.id === blockId
            ? {
                ...b,
                exercises: b.exercises
                  .filter((e) => e.id !== exerciseId)
                  .map((e, idx) => ({ ...e, order: idx })),
              }
            : b
        ),
      },
    }));
  },

  /* -- updateBlockExercise -- */
  updateBlockExercise: (blockId, exerciseId, data): void => {
    set((state) => ({
      wizard: {
        ...state.wizard,
        wizardBlocks: state.wizard.wizardBlocks.map((b) =>
          b.id === blockId
            ? {
                ...b,
                exercises: b.exercises.map((e) =>
                  e.id === exerciseId ? { ...e, ...data } : e
                ),
              }
            : b
        ),
      },
    }));
  },

  /* -- reorderExercisesInBlock -- */
  reorderExercisesInBlock: (blockId, oldIndex, newIndex): void => {
    set((state) => ({
      wizard: {
        ...state.wizard,
        wizardBlocks: state.wizard.wizardBlocks.map((b) => {
          if (b.id !== blockId) return b;
          const exercises = [...b.exercises];
          const [moved] = exercises.splice(oldIndex, 1);
          exercises.splice(newIndex, 0, moved);
          return {
            ...b,
            exercises: exercises.map((e, idx) => ({ ...e, order: idx })),
          };
        }),
      },
    }));
  },

  /* -- reorderBlocks -- */
  reorderBlocks: (oldIndex, newIndex): void => {
    set((state) => {
      const blocks = [...state.wizard.wizardBlocks];
      const [moved] = blocks.splice(oldIndex, 1);
      blocks.splice(newIndex, 0, moved);
      return {
        wizard: {
          ...state.wizard,
          wizardBlocks: blocks.map((b, idx) => ({ ...b, order: idx })),
        },
      };
    });
  },
});

/* ------------------------------------------------------------------ */
/*  Store export                                                       */
/* ------------------------------------------------------------------ */

export const useProgramStore = create<ProgramState>()(
  persist(programStoreFactory, {
    name: 'azfit-programs-storage',
    partialize: (state) => ({
      programs: state.programs,
      wizard: state.wizard,
    }),
  })
);
