import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import type { StateCreator } from 'zustand';

/* ------------------------------------------------------------------ */
/*  Primitive types                                                    */
/* ------------------------------------------------------------------ */

export type ClientGoal = 'lose-fat' | 'build-muscle' | 'strength' | 'endurance' | 'maintenance';
export type ClientStatus = 'active' | 'on-hold' | 'inactive' | 'prospect' | 'former';
export type Gender = 'male' | 'female' | 'other';

/* ------------------------------------------------------------------ */
/*  Sub-interfaces                                                     */
/* ------------------------------------------------------------------ */

export interface BioPrintEntry {
  id: string;
  date: string;
  site: string;
  value: number;
}

export interface SessionLog {
  id: string;
  date: string;
  type: string;
  duration: number;
  notes?: string;
  status?: string;
  rating?: number;
}

export interface BodyMeasurement {
  id: string;
  date: string;
  weight: number;
  bodyFat?: number;
  chest?: number;
  waist?: number;
  hips?: number;
  arms?: number;
  thighs?: number;
  calves?: number;
  shoulders?: number;
  notes?: string;
}

export interface ProgressPhoto {
  id: string;
  date: string;
  url: string;
  label: 'front' | 'side' | 'back' | 'other';
}

export interface Food {
  name: string;
  portion: string;
  calories: number;
  protein: number;
  carbs: number;
  fats: number;
}

export interface Meal {
  id: string;
  name: string;
  time: string;
  foods: Food[];
}

export interface NutritionPlan {
  id: string;
  name?: string;
  type?: string;
  calories: number;
  dailyCalories?: number;
  protein: number;
  carbs: number;
  fats: number;
  meals: Meal[];
  waterIntake?: number;
  adherence?: number;
}

/* ------------------------------------------------------------------ */
/*  Main Client interface                                              */
/* ------------------------------------------------------------------ */

export interface Client {
  id: string;
  name: string;
  email: string;
  phone?: string;
  dateOfBirth?: string;
  gender?: Gender;
  height?: number;
  goal: ClientGoal;
  status: ClientStatus;
  joinDate: string;
  lastSession?: string;
  progress: number;
  notes?: string;
  avatar?: string;
  avatarUrl?: string;
  bioPrints: BioPrintEntry[];
  assignedProgram: string | null;
  program?: string;
  programHistory: string[];
  sessionLogs: SessionLog[];
  measurements: BodyMeasurement[];
  progressPhotos: ProgressPhoto[];
  nutritionPlan: NutritionPlan | null;
  archived: boolean;
  archivedAt: string | null;
}

/* ------------------------------------------------------------------ */
/*  State & Actions                                                    */
/* ------------------------------------------------------------------ */

interface ClientState {
  /* -- state -- */
  clients: Client[];
  selectedClientId: string | null;
  selectedClients: Client[];

  /* -- actions -- */
  addClient: (client: Omit<Client, 'id'>) => Client;
  updateClient: (id: string, data: Partial<Client>) => void;
  archiveClient: (id: string) => void;
  restoreClient: (id: string) => void;
  setClients: (clients: Client[]) => void;
  selectClient: (id: string | null) => void;
  closeClientTab: (id: string) => void;
  uploadAvatar: (clientId: string, file: File | string) => Promise<string>;
  selectedClient: Client | null | undefined;
}

/* ------------------------------------------------------------------ */
/*  Helpers                                                            */
/* ------------------------------------------------------------------ */

function generateClientId(): string {
  return `cli_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;
}

/* ------------------------------------------------------------------ */
/*  Store factory                                                      */
/* ------------------------------------------------------------------ */

const clientStoreFactory: StateCreator<ClientState> = (set, get) => ({
  /* -- initial state -- */
  clients: [],
  selectedClientId: null,
  selectedClients: [],
  get selectedClient() {
    const state = get();
    return state.clients.find((c) => c.id === state.selectedClientId);
  },

  /* -- addClient -- */
  addClient: (client: Omit<Client, 'id'>): Client => {
    const id = generateClientId();
    const newClient: Client = { ...client, id };
    set((state) => ({
      clients: [...state.clients, newClient],
    }));
    return newClient;
  },

  /* -- updateClient -- */
  updateClient: (id: string, data: Partial<Client>): void => {
    set((state) => ({
      clients: state.clients.map((c) =>
        c.id === id ? { ...c, ...data } : c
      ),
    }));
  },

  /* -- archiveClient -- */
  archiveClient: (id: string): void => {
    set((state) => ({
      clients: state.clients.map((c) =>
        c.id === id
          ? { ...c, archived: true, archivedAt: new Date().toISOString(), status: 'inactive' as ClientStatus }
          : c
      ),
    }));
  },

  /* -- restoreClient -- */
  restoreClient: (id: string): void => {
    set((state) => ({
      clients: state.clients.map((c) =>
        c.id === id
          ? { ...c, archived: false, archivedAt: null, status: 'active' as ClientStatus }
          : c
      ),
    }));
  },

  /* -- setClients -- */
  setClients: (clients: Client[]): void => {
    set({ clients });
  },

  /* -- selectClient -- */
  selectClient: (id: string | null): void => {
    set((state) => {
      const client = state.clients.find((c) => c.id === id);
      const newSelectedClients = id && client
        ? state.selectedClients.find((c) => c.id === id)
          ? state.selectedClients
          : [...state.selectedClients, client]
        : state.selectedClients;
      return {
        selectedClientId: id,
        selectedClients: newSelectedClients,
      };
    });
  },

  /* -- closeClientTab -- */
  closeClientTab: (id: string): void => {
    set((state) => {
      const remaining = state.selectedClients.filter((c) => c.id !== id);
      return {
        selectedClients: remaining,
        selectedClientId: state.selectedClientId === id ? (remaining.length > 0 ? remaining[remaining.length - 1].id : null) : state.selectedClientId,
      };
    });
  },

  /* -- uploadAvatar -- */
  uploadAvatar: async (clientId: string, file: File | string): Promise<string> => {
    return new Promise((resolve, reject) => {
      if (typeof file === 'string') {
        set((state) => ({
          clients: state.clients.map((c) =>
            c.id === clientId ? { ...c, avatar: file, avatarUrl: file } : c
          ),
        }));
        resolve(file);
        return;
      }
      const reader = new FileReader();
      reader.onload = () => {
        const dataUrl = reader.result as string;
        set((state) => ({
          clients: state.clients.map((c) =>
            c.id === clientId ? { ...c, avatar: dataUrl, avatarUrl: dataUrl } : c
          ),
        }));
        resolve(dataUrl);
      };
      reader.onerror = () => reject(new Error('Failed to read avatar file'));
      reader.readAsDataURL(file);
    });
  },
});

/* ------------------------------------------------------------------ */
/*  Computed hook (selectedClient)                                     */
/* ------------------------------------------------------------------ */

export function useSelectedClient(): Client | null {
  const { clients, selectedClientId } = useClientStore();
  return clients.find((c) => c.id === selectedClientId) ?? null;
}

/* ------------------------------------------------------------------ */
/*  Store export                                                       */
/* ------------------------------------------------------------------ */

export const useClientStore = create<ClientState>()(
  persist(clientStoreFactory, {
    name: 'azfit-clients-storage',
    partialize: (state) => ({
      clients: state.clients,
      selectedClientId: state.selectedClientId,
      selectedClients: state.selectedClients,
    }),
  })
);
