import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import type { StateCreator } from 'zustand';

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

export type UserRole = 'trainer' | 'client' | 'admin';

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  avatar?: string;
}

interface AuthState {
  /* -- state -- */
  isAuthenticated: boolean;
  user: User | null;
  isDemoMode: boolean;

  /* -- actions -- */
  login: (email: string, password: string, role?: UserRole) => Promise<boolean>;
  logout: () => void;
  toggleDemoMode: () => void;
}

/* ------------------------------------------------------------------ */
/*  Store factory                                                      */
/* ------------------------------------------------------------------ */

const authStoreFactory: StateCreator<AuthState> = (set) => ({
  /* -- initial state -- */
  isAuthenticated: false,
  user: null,
  isDemoMode: false,

  /* -- login -- */
  login: async (email: string, password: string, role?: UserRole): Promise<boolean> => {
    const normalizedEmail = email.trim().toLowerCase();
    const normalizedPassword = password.trim();

    if (normalizedEmail === 'trainer@azfit.com' && normalizedPassword === 'password') {
      const resolvedRole = role ?? 'trainer';
      const mockUser: User = {
        id: 'usr_trainer_001',
        name: 'Trainer User',
        email: normalizedEmail,
        role: resolvedRole,
        avatar: undefined,
      };

      set({
        isAuthenticated: true,
        user: mockUser,
      });
      return true;
    }

    return false;
  },

  /* -- logout -- */
  logout: () => {
    set({
      isAuthenticated: false,
      user: null,
      isDemoMode: false,
    });
  },

  /* -- demo mode toggle -- */
  toggleDemoMode: () => {
    set((state) => ({ isDemoMode: !state.isDemoMode }));
  },
});

/* ------------------------------------------------------------------ */
/*  Store export                                                       */
/* ------------------------------------------------------------------ */

export const useAuthStore = create<AuthState>()(
  persist(authStoreFactory, {
    name: 'azfit-auth-storage',
    partialize: (state) => ({
      isAuthenticated: state.isAuthenticated,
      user: state.user,
      isDemoMode: state.isDemoMode,
    }),
  })
);
