import { create } from 'zustand';

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

export type Theme = 'light' | 'dark' | 'system';
export type AccentColor = 'cyan' | 'green' | 'blue' | 'purple' | 'pink';
export type FontSize = 'small' | 'medium' | 'large';
export type SidebarMode = 'expanded' | 'collapsed' | 'auto';
export type DashboardDensity = 'compact' | 'comfortable' | 'spacious';
export type NotificationFrequency = 'immediate' | 'daily' | 'weekly';

export interface DisplayPreferences {
  showKPICards: boolean;
  showTodaySchedule: boolean;
  showFollowUps: boolean;
  showSparklines: boolean;
  showRecentNotifications: boolean;
  showQuickActionFABs: boolean;
  showMultiClientBar: boolean;
  showAIChatBubble: boolean;
  showBirthdayReminders: boolean;
  showProgressAlerts: boolean;
  showMarketingAnalytics: boolean;
  showTeamPerformance: boolean;
}

export interface NotificationSettings {
  emailNewClient: boolean;
  emailSessionReminder: boolean;
  emailGoalMilestone: boolean;
  smsSessionReminder: boolean;
  smsCancellation: boolean;
  pushNotifications: boolean;
  inAppSound: boolean;
  frequency: NotificationFrequency;
  quietHoursStart: string;
  quietHoursEnd: string;
}

export interface AppearanceSettings {
  theme: Theme;
  accentColor: AccentColor;
  fontSize: FontSize;
  sidebarMode: SidebarMode;
  dashboardDensity: DashboardDensity;
}

export interface PrivacySettings {
  shareWorkoutWithTrainer: boolean;
  shareNutritionWithTrainer: boolean;
  allowProgressPhotoVisibility: boolean;
  profileDiscoverable: boolean;
  dataAnonymization: boolean;
}

export interface IntegrationSettings {
  appleHealthSync: boolean;
  googleFitSync: boolean;
  fitbitSync: boolean;
  garminSync: boolean;
  myFitnessPalSync: boolean;
  calendarSyncGoogle: boolean;
  calendarSyncOutlook: boolean;
  webhookUrl: string;
}

interface UIState {
  /* ── existing ── */
  sidebarOpen: boolean;
  toggleSidebar: () => void;
  setSidebarOpen: (open: boolean) => void;

  /* ── backward compat: direct theme accessors ── */
  theme: Theme;
  toggleTheme: () => void;
  setTheme: (theme: Theme) => void;
  initTheme: () => void;

  /* ── display preferences ── */
  display: DisplayPreferences;
  setDisplay: (d: Partial<DisplayPreferences>) => void;
  resetDisplay: () => void;

  /* ── notifications ── */
  notifications: NotificationSettings;
  setNotifications: (n: Partial<NotificationSettings>) => void;
  resetNotifications: () => void;

  /* ── appearance ── */
  appearance: AppearanceSettings;
  setAppearance: (a: Partial<AppearanceSettings>) => void;
  resetAppearance: () => void;

  /* ── privacy ── */
  privacy: PrivacySettings;
  setPrivacy: (p: Partial<PrivacySettings>) => void;
  resetPrivacy: () => void;

  /* ── integrations ── */
  integrations: IntegrationSettings;
  setIntegrations: (i: Partial<IntegrationSettings>) => void;
  resetIntegrations: () => void;

  /* ── global reset ── */
  resetAllSettings: () => void;
}

/* ------------------------------------------------------------------ */
/*  localStorage helpers                                               */
/* ------------------------------------------------------------------ */

const STORAGE_KEY = 'azfit-ui-store-v2';

const defaultDisplay: DisplayPreferences = {
  showKPICards: true,
  showTodaySchedule: true,
  showFollowUps: true,
  showSparklines: true,
  showRecentNotifications: true,
  showQuickActionFABs: true,
  showMultiClientBar: true,
  showAIChatBubble: true,
  showBirthdayReminders: true,
  showProgressAlerts: true,
  showMarketingAnalytics: true,
  showTeamPerformance: true,
};

const defaultNotifications: NotificationSettings = {
  emailNewClient: true,
  emailSessionReminder: true,
  emailGoalMilestone: true,
  smsSessionReminder: false,
  smsCancellation: false,
  pushNotifications: true,
  inAppSound: true,
  frequency: 'immediate',
  quietHoursStart: '22:00',
  quietHoursEnd: '07:00',
};

const defaultAppearance: AppearanceSettings = {
  theme: 'system',
  accentColor: 'cyan',
  fontSize: 'medium',
  sidebarMode: 'expanded',
  dashboardDensity: 'comfortable',
};

const defaultPrivacy: PrivacySettings = {
  shareWorkoutWithTrainer: true,
  shareNutritionWithTrainer: true,
  allowProgressPhotoVisibility: true,
  profileDiscoverable: false,
  dataAnonymization: true,
};

const defaultIntegrations: IntegrationSettings = {
  appleHealthSync: false,
  googleFitSync: false,
  fitbitSync: false,
  garminSync: false,
  myFitnessPalSync: false,
  calendarSyncGoogle: false,
  calendarSyncOutlook: false,
  webhookUrl: '',
};

function loadFromStorage(): {
  display: DisplayPreferences;
  notifications: NotificationSettings;
  appearance: AppearanceSettings;
  privacy: PrivacySettings;
  integrations: IntegrationSettings;
} | null {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

function persistToStorage(state: {
  display: DisplayPreferences;
  notifications: NotificationSettings;
  appearance: AppearanceSettings;
  privacy: PrivacySettings;
  integrations: IntegrationSettings;
}) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  } catch {
    /* ignore */
  }
}

const saved = loadFromStorage();

/* ------------------------------------------------------------------ */
/*  Store                                                              */
/* ------------------------------------------------------------------ */

export const useUIStore = create<UIState>()((set, get) => ({
  /* ── existing ── */
  sidebarOpen: false,
  toggleSidebar: () => set((s) => ({ sidebarOpen: !s.sidebarOpen })),
  setSidebarOpen: (open) => set({ sidebarOpen: open }),

  /* ── backward compat: direct theme accessors ── */
  theme: (saved?.appearance ?? defaultAppearance).theme,
  toggleTheme: () =>
    set((s) => {
      const newTheme = s.appearance.theme === 'dark' ? 'light' : 'dark';
      return { appearance: { ...s.appearance, theme: newTheme }, theme: newTheme };
    }),
  setTheme: (theme) =>
    set((s) => ({ appearance: { ...s.appearance, theme }, theme })),
  initTheme: () => {
    const savedTheme = localStorage.getItem('theme');
    if (savedTheme === 'light' || savedTheme === 'dark' || savedTheme === 'system') {
      set((s) => ({ appearance: { ...s.appearance, theme: savedTheme }, theme: savedTheme }));
    }
  },

  /* ── display preferences ── */
  display: saved?.display ?? { ...defaultDisplay },
  setDisplay: (d) => {
    const next = { ...get().display, ...d };
    set({ display: next });
    persistToStorage({
      display: next,
      notifications: get().notifications,
      appearance: get().appearance,
      privacy: get().privacy,
      integrations: get().integrations,
    });
  },
  resetDisplay: () => {
    set({ display: { ...defaultDisplay } });
    persistToStorage({
      display: { ...defaultDisplay },
      notifications: get().notifications,
      appearance: get().appearance,
      privacy: get().privacy,
      integrations: get().integrations,
    });
  },

  /* ── notifications ── */
  notifications: saved?.notifications ?? { ...defaultNotifications },
  setNotifications: (n) => {
    const next = { ...get().notifications, ...n };
    set({ notifications: next });
    persistToStorage({
      display: get().display,
      notifications: next,
      appearance: get().appearance,
      privacy: get().privacy,
      integrations: get().integrations,
    });
  },
  resetNotifications: () => {
    set({ notifications: { ...defaultNotifications } });
    persistToStorage({
      display: get().display,
      notifications: { ...defaultNotifications },
      appearance: get().appearance,
      privacy: get().privacy,
      integrations: get().integrations,
    });
  },

  /* ── appearance ── */
  appearance: saved?.appearance ?? { ...defaultAppearance },
  setAppearance: (a) => {
    const next = { ...get().appearance, ...a };
    set((s) => ({
      appearance: next,
      theme: a.theme ?? s.theme,
    }));
    persistToStorage({
      display: get().display,
      notifications: get().notifications,
      appearance: next,
      privacy: get().privacy,
      integrations: get().integrations,
    });
  },
  resetAppearance: () => {
    set({ appearance: { ...defaultAppearance } });
    persistToStorage({
      display: get().display,
      notifications: get().notifications,
      appearance: { ...defaultAppearance },
      privacy: get().privacy,
      integrations: get().integrations,
    });
  },

  /* ── privacy ── */
  privacy: saved?.privacy ?? { ...defaultPrivacy },
  setPrivacy: (p) => {
    const next = { ...get().privacy, ...p };
    set({ privacy: next });
    persistToStorage({
      display: get().display,
      notifications: get().notifications,
      appearance: get().appearance,
      privacy: next,
      integrations: get().integrations,
    });
  },
  resetPrivacy: () => {
    set({ privacy: { ...defaultPrivacy } });
    persistToStorage({
      display: get().display,
      notifications: get().notifications,
      appearance: get().appearance,
      privacy: { ...defaultPrivacy },
      integrations: get().integrations,
    });
  },

  /* ── integrations ── */
  integrations: saved?.integrations ?? { ...defaultIntegrations },
  setIntegrations: (i) => {
    const next = { ...get().integrations, ...i };
    set({ integrations: next });
    persistToStorage({
      display: get().display,
      notifications: get().notifications,
      appearance: get().appearance,
      privacy: get().privacy,
      integrations: next,
    });
  },
  resetIntegrations: () => {
    set({ integrations: { ...defaultIntegrations } });
    persistToStorage({
      display: get().display,
      notifications: get().notifications,
      appearance: get().appearance,
      privacy: get().privacy,
      integrations: { ...defaultIntegrations },
    });
  },

  /* ── global reset ── */
  resetAllSettings: () => {
    set({
      display: { ...defaultDisplay },
      notifications: { ...defaultNotifications },
      appearance: { ...defaultAppearance },
      privacy: { ...defaultPrivacy },
      integrations: { ...defaultIntegrations },
    });
    persistToStorage({
      display: { ...defaultDisplay },
      notifications: { ...defaultNotifications },
      appearance: { ...defaultAppearance },
      privacy: { ...defaultPrivacy },
      integrations: { ...defaultIntegrations },
    });
  },
}));
